class Solution {
public:
    bool rotateString(string s, string goal) {
        int n = (int)s.size();
        if ((int)goal.size() != n) return false;

        // Build KMP failure function (lps) for pattern = goal
        vector<int> lps(n, 0);
        int len = 0;
        for (int i = 1; i < n; ) {
            if (goal[i] == goal[len]) {
                lps[i] = len + 1;
                ++len;
                ++i;
            } else if (len > 0) {
                len = lps[len - 1];
            } else {
                lps[i] = 0;
                ++i;
            }
        }

        // KMP search for goal inside s + s
        string text = s + s;
        int j = 0;
        for (int i = 0; i < 2 * n; ) {
            if (text[i] == goal[j]) {
                ++i;
                ++j;
                if (j == n) return true;
            } else if (j > 0) {
                j = lps[j - 1];
            } else {
                ++i;
            }
        }
        return false;
    }
};
